-- Keep the recorded task and delivered result; retire file-validation machinery.
ALTER TABLE armi.codex_verification_results DROP CONSTRAINT codex_verification_results_check;
UPDATE armi.codex_verification_results AS result
SET final_result_artifact_id=COALESCE(
    result.final_result_artifact_id,
    (SELECT source.evidence_artifact_id FROM armi.codex_result_sources AS source
     WHERE source.codex_verification_id=result.codex_verification_id),
    result.validation_report_artifact_id)
WHERE result.final_result_artifact_id IS NULL;
ALTER TABLE armi.codex_verification_results
    ALTER COLUMN final_result_artifact_id SET NOT NULL,
    DROP COLUMN source_tree_digest,
    DROP COLUMN final_tree_digest,
    DROP COLUMN patch_digest,
    DROP COLUMN event_transcript_artifact_id,
    DROP COLUMN patch_artifact_id,
    DROP COLUMN result_bundle_artifact_id,
    DROP COLUMN diagnostics_artifact_id,
    DROP COLUMN validation_report_artifact_id,
    DROP COLUMN changed_path_count,
    ADD CONSTRAINT codex_verification_results_check CHECK ((execution_status <> 'verified'::text OR execution_error_code IS NULL));
ALTER TABLE armi.codex_task_sources
    DROP COLUMN source_bundle_artifact_id,
    DROP COLUMN source_bundle_digest,
    DROP COLUMN source_tree_digest,
    DROP COLUMN validator_id;
ALTER TABLE armi.action_intent_revisions DROP CONSTRAINT action_intent_revisions_family_check;
ALTER TABLE armi.action_intent_revisions DROP COLUMN validator_id;
ALTER TABLE armi.schema_baseline_identity DROP CONSTRAINT schema_baseline_identity_value_check;
UPDATE armi.schema_baseline_identity SET baseline_identity='armi.schema-baseline.v27';
ALTER TABLE armi.schema_baseline_identity ADD CONSTRAINT schema_baseline_identity_value_check CHECK (baseline_identity='armi.schema-baseline.v27');
